    h, w = len(g), len(g[0])
    for j, color in enumerate(g[0]):
        if color == 0:
            continue
        matches = [(r, k) for r in range(1, h) for k in range(w)
                   if g[r][k] == color]
        if matches:
            r, k = matches[0]
            for rr in range(1, r):
                if g[rr][j] == 0:
                    g[rr][j] = color
            for kk in range(min(j, k), max(j, k) + 1):
                if g[r][kk] == 0:
                    g[r][kk] = color
        else:
            for rr in range(1, h):
                if g[rr][j] == 0:
                    g[rr][j] = color
    return g

